import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_source = r"""
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

#define BLOCK_SIZE 256

__global__ void layernorm_kernel(
    const float* __restrict__ x,
    float* __restrict__ y,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    int N,
    float eps)
{
    int batch = blockIdx.x;
    const float* x_batch = x + (long long)batch * N;
    float* y_batch = y + (long long)batch * N;

    int tid = threadIdx.x;
    int stride = blockDim.x;

    double sum = 0.0;
    double sumsq = 0.0;

    for (int i = tid; i < N; i += stride) {
        float v = x_batch[i];
        sum += (double)v;
        sumsq += (double)v * (double)v;
    }

    __shared__ double s_sum[BLOCK_SIZE];
    __shared__ double s_sumsq[BLOCK_SIZE];

    s_sum[tid] = sum;
    s_sumsq[tid] = sumsq;
    __syncthreads();

    for (int s = blockDim.x / 2; s > 0; s >>= 1) {
        if (tid < s) {
            s_sum[tid] += s_sum[tid + s];
            s_sumsq[tid] += s_sumsq[tid + s];
        }
        __syncthreads();
    }

    __shared__ float mean;
    __shared__ float inv_std;

    if (tid == 0) {
        double m = s_sum[0] / (double)N;
        double var = s_sumsq[0] / (double)N - m * m;
        mean = (float)m;
        inv_std = (float)(1.0 / sqrt(var + (double)eps));
    }
    __syncthreads();

    for (int i = tid; i < N; i += stride) {
        float v = x_batch[i];
        y_batch[i] = (v - mean) * inv_std * weight[i] + bias[i];
    }
}

torch::Tensor layernorm_cuda(
    torch::Tensor x,
    torch::Tensor weight,
    torch::Tensor bias,
    double eps)
{
    TORCH_CHECK(x.is_cuda(), "x must be a CUDA tensor");
    TORCH_CHECK(weight.is_cuda(), "weight must be a CUDA tensor");
    TORCH_CHECK(bias.is_cuda(), "bias must be a CUDA tensor");

    auto x_contig = x.contiguous();
    auto weight_contig = weight.contiguous();
    auto bias_contig = bias.contiguous();

    auto y = torch::empty_like(x_contig);

    int64_t N = weight_contig.numel();
    int64_t total = x_contig.numel();
    int64_t batch = total / N;

    dim3 grid((unsigned int)batch);
    dim3 block(BLOCK_SIZE);

    layernorm_kernel<<<grid, block>>>(
        x_contig.data_ptr<float>(),
        y.data_ptr<float>(),
        weight_contig.data_ptr<float>(),
        bias_contig.data_ptr<float>(),
        (int)N,
        (float)eps
    );

    return y;
}
"""

cpp_source = r"""
torch::Tensor layernorm_cuda(torch::Tensor x, torch::Tensor weight, torch::Tensor bias, double eps);
"""

layernorm_module = load_inline(
    name="layernorm_module",
    cpp_sources=cpp_source,
    cuda_sources=cuda_source,
    functions=["layernorm_cuda"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Optimized model that performs Layer Normalization using a custom CUDA kernel.
    """
    def __init__(self, normalized_shape: tuple):
        super(ModelNew, self).__init__()
        self.normalized_shape = normalized_shape
        self.weight = nn.Parameter(torch.ones(normalized_shape))
        self.bias = nn.Parameter(torch.zeros(normalized_shape))
        self.eps = 1e-5
        self.layernorm_module = layernorm_module

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        x = x.contiguous()
        weight = self.weight.contiguous()
        bias = self.bias.contiguous()
        return self.layernorm_module.layernorm_cuda(x, weight, bias, self.eps)


batch_size = 16
features = 64
dim1 = 256
dim2 = 256


def get_inputs():
    x = torch.randn(batch_size, features, dim1, dim2)
    mean = 1000
    std_dev = 0.1
    x = x * std_dev + mean
    return [x]


def get_init_inputs():
    return [(features, dim1, dim2)]

